sys_script_include.script:
var ProjectMCPStoryServiceSNC = Class.create();

ProjectMCPStoryServiceSNC.prototype = {

    initialize: function() {
    },

    /**
     * Returns stories associated with a project.
     *
     * @param {String} projectNumber - Project number, e.g. PRJ0010001
     * @param {Object} options - Optional paging settings
     * @returns {Object}
     */
    listForProject: function(projectNumber, options) {
        if (gs.nil(projectNumber)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: project number'
            };
        }

        options = options || {};

        var limit = this._parseInteger(options.limit, 50, 1, 100);
        var offset = this._parseInteger(options.offset, 0, 0, 100000);

        /*
         * Resolve the project number to its sys_id first.
         */
        var project = new GlideRecordSecure('pm_project');
        project.addQuery('number', projectNumber);
        project.setLimit(1);
        project.query();

        if (!project.next()) {
            return {
                success: false,
                status: 404,
                error: 'Project not found: ' + projectNumber
            };
        }

        var projectSysId = project.getUniqueValue();

        /*
         * Request one additional record so we can determine whether
         * another page exists without running a separate count query.
         */
        var story = new GlideRecordSecure('rm_story');
        story.addQuery('project', projectSysId);
        story.orderBy('priority');
        story.orderBy('number');
        story.chooseWindow(offset, offset + limit + 1);
        story.query();

        var stories = [];

        while (story.next()) {
            stories.push(this._serializeStory(story));
        }

        var hasMore = stories.length > limit;

        if (hasMore) {
            stories.pop();
        }

        return {
            success: true,
            status: 200,
            data: {
                project: {
                    sys_id: projectSysId,
                    number: this._value(project, 'number'),
                    short_description: this._value(project, 'short_description')
                },

                stories: stories,

                pagination: {
                    limit: limit,
                    offset: offset,
                    returned: stories.length,
                    has_more: hasMore,
                    next_offset: hasMore ? offset + limit : null
                }
            }
        };
    },

    /**
     * Returns detailed information for a single story.
     *
     * @param {String} number - Story number, e.g. STRY0010001
     * @returns {Object}
     */
    getByNumber: function(number) {
        if (gs.nil(number)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: number'
            };
        }

        var story = new GlideRecordSecure('rm_story');
        story.addQuery('number', number);
        story.setLimit(1);
        story.query();

        if (!story.next()) {
            return {
                success: false,
                status: 404,
                error: 'Story not found: ' + number
            };
        }

        var data = {
            sys_id: story.getUniqueValue(),
            number: this._value(story, 'number'),
            short_description: this._value(story, 'short_description'),
            description: this._value(story, 'description'),
            acceptance_criteria: this._value(story, 'acceptance_criteria'),

            state: this._valueAndDisplay(story, 'state'),
            priority: this._valueAndDisplay(story, 'priority'),
            type: this._valueAndDisplay(story, 'type'),
            classification: this._valueAndDisplay(story, 'classification'),

            points: this._number(story, 'story_points'),
            blocked: this._boolean(story, 'blocked'),
            active: this._boolean(story, 'active'),

            project: this._reference(story, 'project'),
            project_phase: this._reference(story, 'project_phase'),

            assignment_group: this._reference(story, 'assignment_group'),
            assigned_to: this._reference(story, 'assigned_to'),
            sprint: this._reference(story, 'sprint'),

            epic: this._reference(story, 'epic'),
            product: this._reference(story, 'product'),
            release: this._reference(story, 'release'),

            sys_created_on: this._value(story, 'sys_created_on'),
            sys_updated_on: this._value(story, 'sys_updated_on')
        };

        /*
         * Some Story fields vary depending on installed plugins/version.
         * These helpers safely return null when a field does not exist.
         */
        data.theme = this._reference(story, 'theme');
        data.demand = this._reference(story, 'demand');

        /*
         * Journal fields cannot be read meaningfully with getValue().
         * Return the most recent entry for useful MCP context without
         * sending the story's entire activity history.
         */
        data.activity = {
            comments: this._latestJournalEntry(story, 'comments'),
            work_notes: this._latestJournalEntry(story, 'work_notes')
        };

        return {
            success: true,
            status: 200,
            data: data
        };
    },

    /**
     * Serialize a Story for list responses.
     *
     * Keep this intentionally smaller than getByNumber() so a project
     * containing many stories does not produce an unnecessarily large
     * MCP response.
     */
    _serializeStory: function(story) {
        return {
            sys_id: story.getUniqueValue(),
            number: this._value(story, 'number'),
            short_description: this._value(story, 'short_description'),

            state: this._valueAndDisplay(story, 'state'),
            priority: this._valueAndDisplay(story, 'priority'),

            points: this._number(story, 'story_points'),
            blocked: this._boolean(story, 'blocked'),
            active: this._boolean(story, 'active'),

            assignment_group: this._reference(story, 'assignment_group'),
            assigned_to: this._reference(story, 'assigned_to'),
            sprint: this._reference(story, 'sprint'),

            epic: this._reference(story, 'epic'),
            product: this._reference(story, 'product'),
            release: this._reference(story, 'release'),
            project_phase: this._reference(story, 'project_phase'),

            sys_updated_on: this._value(story, 'sys_updated_on')
        };
    },

    /**
     * Return a raw field value or null.
     */
    _value: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        return gs.nil(value) ? null : value;
    },

    /**
     * Return both the raw and display values for a field.
     */
    _valueAndDisplay: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return {
            value: value,
            display_value: gr.getDisplayValue(fieldName)
        };
    },

    /**
     * Return a reference field as its sys_id and display value.
     */
    _reference: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return {
            value: value,
            display_value: gr.getDisplayValue(fieldName)
        };
    },

    /**
     * Return a numeric field as a JavaScript number.
     */
    _number: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        var number = parseFloat(value);

        return isNaN(number) ? null : number;
    },

    /**
     * Return a Glide boolean field as a JavaScript boolean.
     */
    _boolean: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        var value = gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return value == 'true' || value == '1';
    },

    /**
     * Return the most recent entry from a journal field.
     */
    _latestJournalEntry: function(gr, fieldName) {
        if (!gr || !gr.isValidField(fieldName)) {
            return null;
        }

        try {
            var value = gr.getElement(fieldName).getJournalEntry(-1);

            return gs.nil(value) ? null : value;
        } catch (e) {
            return null;
        }
    },

    /**
     * Parse, default, and clamp an integer option.
     */
    _parseInteger: function(value, defaultValue, min, max) {
        var parsed = parseInt(value, 10);

        if (isNaN(parsed)) {
            parsed = defaultValue;
        }

        if (parsed < min) {
            parsed = min;
        }

        if (parsed > max) {
            parsed = max;
        }

        return parsed;
    },

    type: 'ProjectMCPStoryServiceSNC'
};
